class Solution {
public:
    int maxSum(vector<vector<int>>& grid, vector<int>& limits, int k) {
        vector<int> pool;
        for (int i = 0; i < grid.size(); i++) {
            sort(grid[i].rbegin(), grid[i].rend());
            for (int j = 0; j < limits[i] && j < grid[i].size(); j++) pool.push_back(grid[i][j]);
        }
        sort(pool.rbegin(), pool.rend());
        long long ans = 0;
        for (int i = 0; i < k && i < pool.size(); i++) ans += pool[i];
        return (int) ans;
    }
};

