class Solution {
    public int maxSum(int[][] grid, int[] limits, int k) {
        List<Integer> pool = new ArrayList<>();
        for (int i = 0; i < grid.length; i++) {
            Integer[] row = Arrays.stream(grid[i]).boxed().toArray(Integer[]::new);
            Arrays.sort(row, Collections.reverseOrder());
            for (int j = 0; j < limits[i] && j < row.length; j++) pool.add(row[j]);
        }
        pool.sort(Collections.reverseOrder());
        long ans = 0;
        for (int i = 0; i < k && i < pool.size(); i++) ans += pool.get(i);
        return (int) ans;
    }
}

