import heapq
class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        h = []
        for row, lim in zip(grid, limits):
            for v in sorted(row, reverse=True)[:lim]:
                heapq.heappush(h, v)
                if len(h) > k:
                    heapq.heappop(h)
        return sum(h)

