var maxSum = function(grid, limits, k) {
    const h = [];
    const push = v => { h.push(v); let i = h.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
    const pop = () => { const t = h[0]; h[0] = h[h.length - 1]; h.pop(); let i = 0; for (;;) { let s = i; if (2*i+1 < h.length && h[2*i+1] < h[s]) s = 2*i+1; if (2*i+2 < h.length && h[2*i+2] < h[s]) s = 2*i+2; if (s === i) break; [h[s], h[i]] = [h[i], h[s]]; i = s; } return t; };
    grid.forEach((row, i) => { row.sort((a, b) => b - a); for (let j = 0; j < limits[i]; j++) { push(row[j]); if (h.length > k) pop(); } });
    return h.reduce((a, b) => a + b, 0);
};
